#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("EMPTY\n");
        return 0;
    }

    char *str = argv[1];
    int len = strlen(str);
    int start = 0;
    int end = len - 1;

    while (start <= end && (str[start] == ' ' || str[start] == '\t' || str[start] == '\n' || str[start] == '\r')) {
        start++;
    }

    while (start <= end && (str[end] == ' ' || str[end] == '\t' || str[end] == '\n' || str[end] == '\r')) {
        end--;
    }

    if (start > end) {
        printf("EMPTY\n");
    } else {
        for (int i = start; i <= end; i++) {
            printf("%c", str[i]);
        }
        printf("\n");
    }

    return 0;
}
